btnCalc.setOnClickListener(v -> {
    String text = etHours.getText().toString().trim();
    if (text.isEmpty()) {
        etHours.setError("Enter hours");
        return;
    }
    int hours;
    try {
        hours = Integer.parseInt(text);
    } catch (NumberFormatException e) {
        etHours.setError("Numbers only");
        return;
    }
    if (hours <= 0) {
        etHours.setError("Must be > 0");
        return;
    }
    int fee = hours * 100;
    tvResult.setText("Total Fee: Rs. " + fee);
});

